const body = $input.first().json.body || $input.first().json;

let tag = '';
let previousTag = '';
let repo = '';
let owner = '';

if (body.ref_type === 'tag' || (body.ref && body.ref.startsWith('refs/tags/'))) {
  // GitHub tag push event
  tag = body.ref?.replace('refs/tags/', '') || body.release?.tag_name || '';
  repo = body.repository?.name || '';
  owner = body.repository?.owner?.login || body.repository?.owner?.name || '';
} else if (body.tag) {
  // Direct tag field
  tag = body.tag;
  repo = body.repo || body.repository?.name || '';
  owner = body.owner || body.repository?.owner?.login || '';
} else {
  tag = body.release?.tag_name || body.ref || 'unknown';
  repo = body.repository?.name || 'unknown';
  owner = body.repository?.owner?.login || 'unknown';
}

return [{
  json: {
    tag: tag.replace('refs/tags/', ''),
    repo,
    owner,
    timestamp: new Date().toISOString()
  }
}];

const tags = $input.first().json;
const currentTag = $('Parse Deploy Event').first().json.tag;
const owner = $('Parse Deploy Event').first().json.owner;
const repo = $('Parse Deploy Event').first().json.repo;

const tagList = Array.isArray(tags) ? tags : [];
const currentIndex = tagList.findIndex(t => t.name === currentTag);
const previousTag = currentIndex >= 0 && currentIndex < tagList.length - 1
  ? tagList[currentIndex + 1].name
  : tagList.length > 1 ? tagList[1].name : '';

return [{
  json: {
    currentTag,
    previousTag,
    owner,
    repo,
    compareUrl: previousTag
      ? `https://api.github.com/repos/${owner}/${repo}/compare/${previousTag}...${currentTag}`
      : `https://api.github.com/repos/${owner}/${repo}/commits?per_page=20`
  }
}];

const data = $input.first().json;
const info = $('Find Previous Tag').first().json;
const deployInfo = $('Parse Deploy Event').first().json;

const commits = data.commits || (Array.isArray(data) ? data : []);

const categories = {
  feat: [],
  fix: [],
  refactor: [],
  docs: [],
  test: [],
  chore: [],
  perf: [],
  ci: [],
  other: []
};

for (const commit of commits) {
  const msg = commit.commit?.message || commit.message || '';
  const author = commit.commit?.author?.name || commit.author?.login || 'unknown';
  const sha = (commit.sha || '').substring(0, 7);
  const firstLine = msg.split('\n')[0];

  let categorized = false;
  for (const key of Object.keys(categories)) {
    if (key !== 'other' && firstLine.toLowerCase().startsWith(key)) {
      categories[key].push(`- \`${sha}\` ${firstLine} (@${author})`);
      categorized = true;
      break;
    }
  }
  if (!categorized) {
    categories.other.push(`- \`${sha}\` ${firstLine} (@${author})`);
  }
}

let changelog = `# Changelog: ${info.currentTag}\n\n`;
changelog += `**Repository:** ${deployInfo.owner}/${deployInfo.repo}\n`;
changelog += `**Tag:** ${info.currentTag}`;
if (info.previousTag) changelog += ` (from ${info.previousTag})`;
changelog += `\n**Date:** ${deployInfo.timestamp}\n`;
changelog += `**Total Commits:** ${commits.length}\n\n`;

const labels = {
  feat: '🚀 Features',
  fix: '🐛 Bug Fixes',
  refactor: '♻️ Refactoring',
  docs: '📝 Documentation',
  test: '✅ Tests',
  chore: '🔧 Chores',
  perf: '⚡ Performance',
  ci: '🔄 CI/CD',
  other: '📦 Other Changes'
};

for (const [key, items] of Object.entries(categories)) {
  if (items.length > 0) {
    changelog += `## ${labels[key]}\n${items.join('\n')}\n\n`;
  }
}

return [{
  json: {
    changelog,
    currentTag: info.currentTag,
    previousTag: info.previousTag,
    commitCount: commits.length,
    repo: `${deployInfo.owner}/${deployInfo.repo}`,
    timestamp: deployInfo.timestamp
  }
}];
